# ---------------------------------------------------------------- four exercises on the basic analyses
def _anq(rows, heads, cols, widths):
    """Given figures in A:C, answers in the columns of heads; rows: [(label, values...)]."""
    d, g, f, st = {'A1': heads[0]}, {}, {}, {}
    for j, h in enumerate(heads[1:]): d[f'{chr(66 + j)}1'] = h
    for j in range(len(heads)): st[f'{chr(65 + j)}1'] = {'fill': '#e1e7f8', 'b': True}
    for i, row in enumerate(rows):
        r = 2 + i; d[f'A{r}'] = row[0]
        for j, v in enumerate(row[1:]): g[f'{chr(66 + j)}{r}'] = v; f[f'{chr(66 + j)}{r}'] = 'acc0'
    return d, g, f, st


_li = [('הכנסות', 30000, 42000), ('מוצרים שנצרכו', 2500, 3600), ('שכר דירה', 9000, 9600), ('חשמל', 600, 900), ('רווח נקי', 17900, 27900)]
assert 42000 - 3600 - 9600 - 900 == 27900 and 30000 - 2500 - 9000 - 600 == 17900
_d, _g, _f, _s = _anq(_li, ['שורה בדוח', 'שנת 2026', 'שנת 2027', 'שינוי בש״ח', 'שינוי ב-%'], 3, None)
_sol, _stp = {}, []
for _i, (_n, _a, _b) in enumerate(_li):
    _r = 2 + _i; _sol[f'D{_r}'] = f'=C{_r}-B{_r}'; _sol[f'E{_r}'] = f'=D{_r}/B{_r}'; _f[f'D{_r}'] = 'acc0'; _f[f'E{_r}'] = 'pct1'
    _stp.append(dict(cells={f'D{_r}': f'=C{_r}-B{_r}', f'E{_r}': f'=D{_r}/B{_r}'}, note=f'<b>{_n}:</b> {_b - _a:,} ש״ח, כלומר {(_b - _a) / _a * 100:.1f}%.', sel=f'D{_r}'))
